import { transparentize } from "polished";
import {
  IconCheckCircle,
  IconClose,
  IconInfo,
  IconWarning,
  IconCancel,
} from "@airbus/icons";
import { focus, svgColor, svgUri } from "../../helpers";
import { Button, buttonVariant } from "../Button";
import { StyleFn } from "..";

export const Banner: StyleFn = (theme, mode) => {
  const { color, font, size, elevation } = theme;
  const { root: rootButtonStyles } = Button(theme, mode);
  const { focusWithPseudo } = focus(theme, mode);
  const textColor = color.text.neutral.minimal[mode];

  return {
    root: {
      zIndex: elevation.zindex.banner,
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      fontSize: font.size.small,
      fontWeight: font.weight.bold,
      lineHeight: font.lineheight.small,
      minHeight: size.spacing[56],
      height: "100%",
      padding: `${size.spacing[8]} ${size.spacing[16]}`,
      paddingLeft: size.spacing[48],
      color: textColor,
      backgroundColor: color.surface.feedback.information.default[mode],
      position: "relative",
      "&:before": {
        position: "absolute",
        content: "''",
        top: 0,
        left: size.spacing[16],
        bottom: 0,
        width: size.spacing[24],
        backgroundRepeat: "no-repeat",
        backgroundPosition: "left 0 top 50%",
        backgroundImage: svgUri(svgColor(IconInfo.data, textColor)),
      },
    },
    _info: {
       "& $removeBtn": {
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.neutral.white.light : "#fff", // Workaround for dark mode
        },
      },
      "& a": {
        // FIX: The color is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
        color: mode === "dark" ? color.text.feedback.information.onsurface.dark : color.text.feedback.information.onsurface.light,
        "&:visited": { 
          color: "currentColor",
        },
        "&:hover": { 
          color: mode === "dark" ? color.palette.yellow["10"] : color.palette.green["30"]
        },
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.neutral.white.light : "#fff", // Workaround for dark mode
        },
      },
    },
    _success: {
      backgroundColor: color.surface.feedback.success.default[mode],
      "&:before": {
        backgroundImage: svgUri(svgColor(IconCheckCircle.data, textColor)),
      },
      "& $removeBtn": {
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.accent.focus.light : color.border.neutral.white.light,
        },
      },
      "& a": {
        // FIX: The color is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
        color: mode === "dark" ? color.text.feedback.success.onsurface.dark : color.text.feedback.success.onsurface.light,
        "&:visited": { 
          color: "currentColor",
        },
        "&:hover": { 
          color: mode === "dark" ? color.palette.pink["70"] : color.palette.green["30"],
        },
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.accent.focus.light : color.border.neutral.white.light,
        },
      },
    },
    _warning: {
      color: color.text.feedback.warning.onsurface[mode],
      backgroundColor: color.surface.feedback.warning.default[mode],
      "&:before": {
        backgroundImage: svgUri(IconWarning.data),
      },
      "& $removeBtn": {
         backgroundImage: svgUri(
          svgColor(IconClose.data, color.text.feedback.warning.onsurface[mode])
        ),
        "&:focus-visible:after": {
          // FIX: The borderColor is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
          // This global selector has higher specificity and can override local styles in dark mode.
          // We have hard-coded hex value (e.g. "#255fccfc") to maintian same color for dark and light mode.
          borderColor: mode === "dark" ? color.border.accent.focus.light : "#255fccfc",
        },
      },
      "& a": {
        // FIX: The color is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
        color: mode === "dark" ? color.text.feedback.warning.onsurface[mode] : "#14171dfc",
         "&:visited": { 
          color: "currentColor",
        },
        "&:hover": { 
          color:  mode === "dark" ? color.border.accent.focus.light : "#255fccfc",
        },
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.accent.focus.light : "#255fccfc",
        },
      },
    },
    _error: {
      backgroundColor: color.surface.feedback.error.default[mode],
      "&:before": {
        backgroundImage: svgUri(svgColor(IconCancel.data, textColor)),
      },
       "& $removeBtn": {
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.neutral.white.light : "#fff", // Workaround for dark mode
        },
      },
       "& a": {
        // FIX: The color is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
        color: mode === "dark" ? color.text.feedback.error.onsurface.dark : color.text.feedback.error.onsurface.light,
         "&:visited": { 
          color: "currentColor",
        },
        "&:hover": { 
          color: mode === "dark" ? color.palette.limeyellow["20"] : color.text.neutral.default.light,
        },
        "&:focus-visible:after": {
          borderColor: mode === "dark" ? color.border.neutral.white.light : "#fff", // Workaround for dark mode
        },
      },
    },
    removeBtn: {
      extend: [
        rootButtonStyles,
        buttonVariant(theme, mode, "ghost"),
        focusWithPseudo({ colorForce: textColor }),
      ],
      marginLeft: size.spacing[40],
      minWidth: size.spacing[40],
      minHeight: size.spacing[40],
      height: "100%",
      padding: size.spacing[2],
      backgroundImage: svgUri(svgColor(IconClose.data, textColor)),
      backgroundRepeat: "no-repeat",
      backgroundPosition: "left 50% top 50%",
      backgroundColor: "transparent",
      "&:hover": {
        backgroundColor: transparentize(0.7, textColor),
      },
      "&:active": {
        backgroundColor: transparentize(0.5, textColor),
      },
    },
  };
};
